     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        Room room = rooms.find(request.roomNumber())
    35	                .orElseThrow(() -> new HotelException(
    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    37	        if (request.guests() > room.capacity()) {
    38	            throw new HotelException(
    39	                    ErrorCode.CAPACITY_EXCEEDED,
    40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    41	        }
    42	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    43	            throw new HotelException(
    44	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    45	        }
    46	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
    47	        RatePlanStrategy strategy = request.ratePlan().strategy();
    48	        strategy.validate(room, request.checkIn(), request.checkOut(), nights, request.companyCode());
    49	        Price price = strategy.calculatePrice(room, request.checkIn(), request.checkOut(), request.companyCode());
    50	        return store.add(request, price);
    51	    }
    52	
    53	    public Reservation find(long reservationId) {
    54	        return store.find(reservationId)
    55	                .orElseThrow(() -> new HotelException(
    56	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    57	    }
    58	
    59	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    60	    public synchronized Reservation confirm(long reservationId) {
    61	        Reservation reservation = find(reservationId);
    62	        if (reservation.status() != ReservationStatus.PENDING) {
    63	            throw notAllowed(reservation, "confirm");
    64	        }
    65	        reservation.confirmPayment();
    66	        store.update(reservation);
    67	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    68	        emailSender.send(
    69	                reservation.guest().email(),
    70	                "Reserva confirmada - " + HOTEL_NAME,
    71	                confirmationEmailBody(reservation, receipt));
    72	        return reservation;
    73	    }
    74	
    75	    /**
    76	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    77	     * reservation was never paid, so nothing comes back).
    78	     */
    79	    public synchronized Reservation cancel(long reservationId) {
    80	        Reservation reservation = find(reservationId);
    81	        if (reservation.status() != ReservationStatus.PENDING
    82	                && reservation.status() != ReservationStatus.CONFIRMED) {
    83	            throw notAllowed(reservation, "cancel");
    84	        }
    85	        RatePlanStrategy strategy = reservation.ratePlan().strategy();
    86	        BigDecimal refund = strategy.calculateRefund(reservation.price(), reservation.status());
    87	        reservation.cancel(refund);
    88	        store.update(reservation);
    89	        return reservation;
    90	    }
    91	
    92	    public synchronized Reservation checkIn(long reservationId) {
    93	        Reservation reservation = find(reservationId);
    94	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    95	            throw notAllowed(reservation, "check in");
    96	        }
    97	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    98	        store.update(reservation);
    99	        return reservation;
   100	    }
   101	
   102	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   103	    public synchronized ReservationReceipt checkOut(long reservationId) {
   104	        Reservation reservation = find(reservationId);
   105	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   106	            throw notAllowed(reservation, "check out");
   107	        }
   108	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   109	        store.update(reservation);
   110	        return new ReservationReceipt(reservation, roomOf(reservation));
   111	    }
   112	
   113	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   114	    public ReservationReceipt receiptCopy(long reservationId) {
   115	        Reservation reservation = find(reservationId);
   116	        if (!reservation.isPaid()) {
   117	            throw notAllowed(reservation, "issue a receipt for");
   118	        }
   119	        return new ReservationReceipt(reservation, roomOf(reservation));
   120	    }
   121	
   122	    private Room roomOf(Reservation reservation) {
   123	        return rooms.find(reservation.roomNumber()).orElseThrow();
   124	    }
   125	
   126	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   127	        return "Olá, " + reservation.guest().name() + "!\n\n"
   128	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   129	                + receipt.text() + "\n"
   130	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   131	                + "Até breve!\n";
   132	    }
   133	
   134	    private static HotelException notAllowed(Reservation reservation, String operation) {
   135	        return new HotelException(
   136	                ErrorCode.OPERATION_NOT_ALLOWED,
   137	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   138	    }
   139	}
